        },
        saveResult(){
            this.form.menu = '';
            this.tableData.forEach(item=>{
                if(item.data_a){
                    if(item.data_a.checked == true)
                        this.form.menu += this.form.menu.length == 0 ? item.data_a.menu_id : (','+item.data_a.menu_id)
                }

