        addNewManager(){
            if(!this.form.dept_id){
                this.$message({
                    message: this.$t('devtable.qxzbm'),
                    type: 'warning'
                }) 
                return false
            }
            const params = {
                method: methodlist.ee_manager_add,
                agent_id: this.UserInfo.agent_id,             
                name: this.form.name,
                password: this.$md5(this.form.password),
                mobile: this.form.mobile,
                type: this.form.type,
                menu: this.form.menu,
                dept_id: this.form.dept_id
            }

            this.$serve(params).then(res => {
                console.log(res);
                if(res.data.code == 0){
                    this.$message({
                        message: this.$t('devtable.tjcg'),
                        type: 'success'
                    })
                    this.dialogFormVisible = false;
                    this.$emit("addManagerSuccess");
                }else{
                    if(res.data.code == -4){
                        this.$message({
                            message: this.$t('devtable.tjsbxmycz'),
                            type: 'warning'
                        }) 
                    }else{
                        this.$message({
                            message: this.$t('devtable.tjsb'),
                            type: 'warning'
                        }) 
                    }
                }
            })
        },
